@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1213  cases=38
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-137
  @fn seedItems(h, takes, srcLen)  @ 153-158
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 160-169

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 173-181
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 184-193
  @case 'focusState before any render returns both bits false'  [harness]  @ 196-203
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 209-222
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 226-243
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 249-270
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 276-294
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 301-319
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 325-358
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 362-386
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 392-422
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 426-447
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 451-464
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 470-504
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 508-522
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 526-549
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 556-573
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 577-600
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 604-627
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 631-666
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 670-686
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 693-720
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 724-748
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 755-776
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 782-806
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 813-832
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 836-855
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 859-881
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 887-905
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 909-927
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 931-953
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 957-981
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 987-1042
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1050-1079
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1085-1128
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1134-1148
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1155-1187
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1191-1211

